import { sql } from 'drizzle-orm';
import {
  bigint,
  char,
  check,
  datetime,
  index,
  int,
  json,
  mysqlEnum,
  mysqlTable,
  timestamp,
  uniqueIndex,
} from 'drizzle-orm/mysql-core';
import type { ConcursosRoomSnapshotV1 } from '@api/boffmedia/concursos/concursos-room-snapshot-v1';

export const CONCURSOS_ROOM_STATUSES = ['lobby', 'playing', 'closed'] as const;
export const CONCURSOS_SNAPSHOT_VERSION = 1;

export function defineConcursosSalas(name: string) {
  return mysqlTable(
    name,
    {
      // UUID generated by the repository before inserting the new room.
      id: char('id', { length: 36 }).primaryKey(),
      code: char('code', { length: 6 }).notNull(),
      hostHash: char('host_hash', { length: 64 }).notNull(),
      status: mysqlEnum('status', CONCURSOS_ROOM_STATUSES)
        .notNull()
        .default('lobby'),

      // Derived by MySQL: one active room per capability; closed rooms use NULL.
      activeHostHash: char('active_host_hash', {
        length: 64,
      }).generatedAlwaysAs(
        sql`case when \`status\` in ('lobby', 'playing') then rtrim(\`host_hash\`) else null end`,
        { mode: 'stored' },
      ),

      snapshotVersion: int('snapshot_version', { unsigned: true })
        .notNull()
        .default(CONCURSOS_SNAPSHOT_VERSION),
      revision: bigint('revision', { mode: 'bigint', unsigned: true })
        .notNull()
        .default(sql`1`),
      snapshot: json('snapshot').$type<ConcursosRoomSnapshotV1>().notNull(),

      // Absolute recovery limit; UTC, millisecond precision, supplied by repository.
      expiresAt: datetime('expires_at', { mode: 'date', fsp: 3 }).notNull(),
      createdAt: timestamp('created_at', { mode: 'date' })
        .notNull()
        .defaultNow(),
      updatedAt: timestamp('updated_at', { mode: 'date' })
        .notNull()
        .defaultNow()
        .onUpdateNow(),
      // Durable close/tombstone instant; physical cleanup after current retention.
      deletedAt: timestamp('deleted_at', { mode: 'date', fsp: 3 }),
    },
    (t) => [
      uniqueIndex(`${name}_code_uq`).on(t.code),
      uniqueIndex(`${name}_active_host_uq`).on(t.activeHostHash),
      index(`${name}_host_status_idx`).on(t.hostHash, t.status),
      index(`${name}_status_expires_idx`).on(t.status, t.expiresAt),
      index(`${name}_status_deleted_idx`).on(t.status, t.deletedAt),
      check(`${name}_version_ck`, sql`${t.snapshotVersion} >= 1`),
      check(`${name}_revision_ck`, sql`${t.revision} >= 1`),
      check(
        `${name}_lifecycle_ck`,
        sql`(${t.status} = 'closed' and ${t.deletedAt} is not null)
        or (${t.status} in ('lobby', 'playing') and ${t.deletedAt} is null)`,
      ),
    ],
  );
}
export const concursosSalas = defineConcursosSalas('concursos_salas');

export type ConcursosSala = typeof concursosSalas.$inferSelect;
export type NewConcursosSala = typeof concursosSalas.$inferInsert;
